/* ------TURN ON LED at GPIO-D-12 pin-----------------
 * 1st task: set --> bitWise OR
 * Address of Clock enable Control Register (AHB1ENR)
 * 0x40023800(base address of RCC) + 0x30 (Address Offset) = 0x40023830
 * 2nd task: clearing --> bitWise AND(&) and set --> bitWise OR(|)
 * Address of the GPIOD mode register (Used to controll mode)
 * 0x40020C00 + 0x00 = 0x40020C00  	---> GPIO-D(port)-12(pin)
 * 3rd task
 * Address of the GPIOD output data register (Used to write)
 * 0x40020C00 + 0x14 = 0x40020C14
 */

#include <stdint.h>



int main(void)
{
	uint32_t *pClkCtrlReg = (uint32_t*)0x40023830;	/*pointer entity*/
	uint32_t *pPortDModeReg = (uint32_t*)0x40020C00;
	uint32_t *pPortDOutReg = (uint32_t*)0x40020C14;

	//__________________________ 1st task ________________________________
	//1. enable the clock for GPIOD peripheral in the AHB1ENR
	// mask value : 0x0000 0008 to set bit at desired pin: bitwise-OR will be applied

	  /*unint32_t temp = *pClkCtrlReg; 	// read operation: de-referencing the pointer
	temp = temp | 0x08;				// modify
	*pClkCtrlReg = temp ;*/

	// 3 line --> code replacement
	// *pClkCtrlReg = *pClkCtrlReg | 0x08;
	*pClkCtrlReg |= 0x08; 				// C code-- shorthand notation


	//__________________________ 2nd task ________________________________
	//2. configure the mode of the IO pin as output
	// a. CLEAR 25th and 24th bit position: mask value for 12 pin : 0xFCFF FFFF
	//*pPortDModeReg = *pPortDModeReg & 0xFCFFFFFF;
	*pPortDModeReg &= 0xFCFFFFFF;
	// b. SET 24th bit position as 1: mask value for 12 pin : 0x0100 0000
	//*pPortDModeReg = *pPortDModeReg | 0x01000000;
	*pPortDModeReg |= 0x01000000;


	//__________________________ 3rd task ________________________________
	//3. SET 12th bit of the output data register to make I/O pin-12 HIGH
	// mask value : 0x1000
	*pPortDOutReg |= 0x1000;


    /* Loop forever */
	// for(;;);
	while(1);
}
